INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 12, 'theory', 'Quiz: memory');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 0, 'How does ROM differ from RAM?', '["ROM contents are set by the circuit and never change, while RAM can be both read and written", "ROM is faster", "RAM keeps data without power", "ROM cannot be read"]', 0, 'ROM is "wired in" at manufacture; RAM is rewritable memory that forgets its data when the power goes off.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 1, 'How many words can three address bits address?', '["3", "6", "8", "9"]', 2, 'The number of distinct combinations is 2³ = 8. An address of k bits tells apart 2 to the power k words.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 2, 'How is the ROM selected in the example memory map?', '["By address 7", "By addresses 0–3: the decoder lights the Rom signal", "By the write signal", "By any address"]', 1, 'The high address bits determine which device is selected. Exactly one of the signals Rom, Ram, Io is lit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 3, 'What happens if Rd and Wr arrive at the same time?', '["Both operations are performed", "Nothing happens and the circuit hangs", "The same cell is read and written", "The write wins and the data output is blocked"]', 3, 'You can''t read and write at once: We = CS · Wr, and Oe = CS · Rd · not We, so the output is disabled.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 12, 4, 'Why is DRAM cheaper than SRAM but needs refreshing?', '["It has no transistors", "It stores data only in registers", "A cell is one transistor and a capacitor, and the capacitor''s charge leaks away", "DRAM is slow, so it is cheap"]', 2, 'SRAM is built from six transistors: fast but expensive. In DRAM the data is held by a charge that drains over time, so it is refreshed periodically.');
